[CmdletBinding()]
param([string]$ProjectRoot='.',[ValidateSet('initial_audit','repair_batch','final_audit')][string]$Event='repair_batch',[switch]$Apply)
$ErrorActionPreference='Stop';$Root=(Resolve-Path -LiteralPath $ProjectRoot).Path;$Agy=Join-Path $Root '.agy';$Wi=Get-Content (Join-Path $Agy 'WORK_ITEM.json') -Raw|ConvertFrom-Json;$Path=Join-Path $Agy 'REPAIR_HISTORY.json';$Utf8=[Text.UTF8Encoding]::new($false)
$State=if(Test-Path $Path){Get-Content $Path -Raw|ConvertFrom-Json}else{[pscustomobject]@{schema_version='2.0.0';work_item_id=$Wi.work_item_id;repair_budget='disabled';initial_audits_observed=0;repair_iterations_observed=0;final_audits_observed=0;history=@()}}
$Field=@{initial_audit='initial_audits_observed';repair_batch='repair_iterations_observed';final_audit='final_audits_observed'}[$Event];$State.$Field=[int]$State.$Field+1;$Now=(Get-Date).ToUniversalTime().ToString('o');$State.history=@($State.history)+@([pscustomobject]@{event=$Event;ordinal=[int]$State.$Field;at_utc=$Now;budget_effect='none'});$State.updated_at_utc=$Now
if($Apply){[IO.File]::WriteAllText($Path,($State|ConvertTo-Json -Depth 20),$Utf8);Write-Host "Registered $Event as observational history. No repair limit exists."}else{$State|ConvertTo-Json -Depth 20}
